#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> generate_lucky_numbers(int max_n) {
    vector<int> lucky;
    vector<int> digits = {4, 7};
    for (int length = 1; length <= 10; ++length) {
        vector<int> current;
        for (int d : digits) {
            current.push_back(d);
        }
        for (int l = 1; l < length; ++l) {
            vector<int> temp;
            for (int num : current) {
                temp.push_back(num * 10 + 4);
                temp.push_back(num * 10 + 7);
            }
            current = temp;
        }
        for (int num : current) {
            if (num <= max_n) {
                lucky.push_back(num);
            }
        }
    }
    sort(lucky.begin(), lucky.end());
    return lucky;
}

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> lucky_numbers = generate_lucky_numbers(n);

    int m = 0;
    long long fact = 1;
    while (m < n && fact < k) {
        m++;
        if (m > 20) break; // Prevent overflow, since 20! is huge
        fact *= m;
    }

    if (m == n && fact < k) {
        cout << -1 << endl;
        return 0;
    }

    // The permutation is identity except for the last m elements
    // Compute the last m elements
    vector<int> perm;
    if (m == 0) {
        perm = {};
    } else {
        vector<int> nums;
        for (int i = n - m + 1; i <= n; ++i) {
            nums.push_back(i);
        }
        // Generate the (k-1)th permutation of nums (0-based)
        k--;
        for (int i = 0; i < m; ++i) {
            int f = 1;
            for (int j = 1; j <= m - i - 1; ++j) {
                f *= j;
            }
            int idx = k / f;
            perm.push_back(nums[idx]);
            nums.erase(nums.begin() + idx);
            k %= f;
        }
    }

    // Now, check all positions. The first (n - m) positions are identity.
    // The last m positions are in perm.
    int count = 0;

    // Check the first (n - m) positions
    for (int pos : lucky_numbers) {
        if (pos <= n - m) {
            count++;
        }
    }

    // Check the last m positions
    for (int i = 0; i < m; ++i) {
        int pos = n - m + 1 + i;
        if (pos > n) continue;
        if (binary_search(lucky_numbers.begin(), lucky_numbers.end(), pos)) {
            if (binary_search(lucky_numbers.begin(), lucky_numbers.end(), perm[i])) {
                count++;
            }
        }
    }

    cout << count << endl;

    return 0;
