#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

vector<int> generate_lucky_numbers(int max_limit) {
    vector<int> lucky;
    queue<int> q;
    q.push(4);
    q.push(7);
    while (!q.empty()) {
        int num = q.front();
        q.pop();
        if (num > max_limit) continue;
        lucky.push_back(num);
        q.push(num * 10 + 4);
        q.push(num * 10 + 7);
    }
    sort(lucky.begin(), lucky.end());
    return lucky;
}

int main() {
    long long n, k;
    cin >> n >> k;

    // Find the maximum m such that m! < k
    long long m = 0;
    long long fact = 1;
    while (true) {
        if (fact >= k) break;
        m++;
        if (m > 20) break; // To prevent overflow, since 20! is huge
        long long next_fact = fact * m;
        if (next_fact < fact) break; // Overflow check
        fact = next_fact;
    }

    if (m > n) {
        cout << -1 << endl;
        return 0;
    }

    // Generate all lucky numbers up to n
    vector<int> lucky_numbers = generate_lucky_numbers(n);
    vector<bool> is_lucky(n + 1, false);
    for (int num : lucky_numbers) {
        if (num <= n) is_lucky[num] = true;
    }

    int count = 0;

    // Check the first part (1 to n - m)
    for (int i = 1; i <= n - m; ++i) {
        if (is_lucky[i] && is_lucky[i]) {
            count++;
        }
    }

    // Generate the k-th permutation of the last m elements
    vector<int> elements;
    for (int i = n - m + 1; i <= n; ++i) {
        elements.push_back(i);
    }

    // Compute the permutation for the last m elements
    vector<int> perm;
    long long current_k = k - 1; // 0-based index
    vector<int> temp = elements;
    for (int i = m; i > 0; --i) {
        long long f = 1;
        for (int j = 1; j < i; ++j) {
            f *= j;
        }
        int index = current_k / f;
        perm.push_back(temp[index]);
        temp.erase(temp.begin() + index);
        current_k %= f;
    }

    // Check the last m positions
    for (int i = 0; i < m; ++i) {
        int pos = (n - m + 1) + i;
        int val = perm[i];
        if (pos <= n && val <= n && is_lucky[pos] && is_lucky[val]) {
            count++;
        }
    }

    cout << count << endl;

    return 0;
}
